dtsPropsFor.Button:
children?: React.ReactNode;
  /** 视觉变体；default 与 outline 当前同观感（产品既定），destructive 为浅红危险态 */
  variant?: "default" | "outline" | "secondary" | "ghost" | "destructive" | "link";
  /** icon* 为方形图标钮尺寸 */
  size?: "default" | "xs" | "sm" | "lg" | "icon" | "icon-xs" | "icon-sm" | "icon-lg";
  /** true 时以 Slot 渲染子元素（如包 <a>） */
  asChild?: boolean;
  disabled?: boolean;
  className?: string;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;

dtsPropsFor.IconButton:
/** 无障碍名，同时作为原生 title 提示 */
  label: string;
  /** 图标子元素（lucide 图标等，svg 尺寸随 size 自动设定） */
  children: React.ReactNode;
  size?: "sm" | "xs" | "2xs";
  tone?: "default" | "danger";
  /** hover/hover-focus 需父级带 group 类才会浮现 */
  reveal?: "always" | "hover" | "hover-focus";
  /** true 时带描边+浮起底（悬浮工具条场景） */
  surface?: boolean;
  /** 开关型按钮按下态：驱动 aria-pressed 与视觉 */
  pressed?: boolean;
  /** 外包 Tooltip 时传 false 防双提示 */
  withTitle?: boolean;
  /** 默认 true：阻断冒泡避免触发所在卡片/行的 onClick */
  stopPropagation?: boolean;
  disabled?: boolean;
  className?: string;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;

dtsPropsFor.Kbd:
/** 键帽文本，如 ⌘⏎ */
  children: React.ReactNode;
  /** true = 按钮标签内的裸字提示（无边框底） */
  inline?: boolean;
  className?: string;

dtsPropsFor.Segmented:
/** 当前选中值 */
  value: string;
  options: { value: string; label: React.ReactNode; title?: string }[];
  onChange: (v: string) => void;
  size?: "sm" | "xs";
  ariaLabel?: string;
  className?: string;

dtsPropsFor.ProgressBar:
/** 进度 0-100（内部自动夹取） */
  value: number;
  /** true 时填充条叠加 glass-sheen-flat 薄光泽 */
  tactile?: boolean;
  className?: string;

dtsPropsFor.EmptyState:
title: string;
  hint?: React.ReactNode;
  icon?: React.ReactNode;
  /** inline = 列表内轻量单行；full = 完整 icon/标题/提示结构 */
  variant?: "full" | "inline";
  className?: string;

dtsPropsFor.PillInput:
value: string;
  onChange: (v: string) => void;
  onSubmit: () => void;
  placeholder: string;
  /** true = textarea（Enter 提交 / Shift+Enter 换行 / 自适应高度） */
  multiline?: boolean;
  /** spark = 灵感模式紫色壳 */
  tone?: "default" | "spark";
  /** 左槽（如模式切换钮） */
  leftSlot?: React.ReactNode;
  /** 提交钮的无障碍名，默认「添加」 */
  submitLabel?: string;
  disabled?: boolean;
  /** 粘贴含图片时回调 */
  onPasteImage?: () => void;
  /** 输入行上方附件区（缩略 chips） */
  attachmentsSlot?: React.ReactNode;
  /** 文本为空也允许提交（有附件场景） */
  canSubmitEmpty?: boolean;
  className?: string;

dtsPropsFor.Switch:
checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  disabled?: boolean;
  size?: "sm" | "default";
  className?: string;

dtsPropsFor.GlowingEffect:
/** 绝对定位铺满最近的定位祖先，沿其边框画鼠标追踪光弧；父容器需 relative + 圆角 */
  blur?: number;
  /** 中心死区半径系数 0-1 */
  inactiveZone?: number;
  /** 容器外多少 px 内仍算命中 */
  proximity?: number;
  /** 弧长的一半（度） */
  spread?: number;
  /** 追随动画时长（秒） */
  movementDuration?: number;
  borderWidth?: number;
  disabled?: boolean;
  className?: string;

dtsPropsFor.Popover:
children?: React.ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  modal?: boolean;

dtsPropsFor.PopoverTrigger:
children?: React.ReactNode;
  /** true 时把触发行为合并进子元素（常配 Button） */
  asChild?: boolean;

dtsPropsFor.PopoverContent:
/** 默认 w-72 白纸面板，带入场动画与 ring 描边 */
  children?: React.ReactNode;
  side?: "top" | "right" | "bottom" | "left";
  sideOffset?: number;
  align?: "start" | "center" | "end";
  alignOffset?: number;
  collisionPadding?: number;
  className?: string;

dtsPropsFor.PopoverHeader:
/** Content 内的标题区容器（竖排 gap-0.5） */
  children?: React.ReactNode;
  className?: string;

dtsPropsFor.PopoverDescription:
/** muted 说明文字 */
  children?: React.ReactNode;
  className?: string;

dtsPropsFor.Tooltip:
children?: React.ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  delayDuration?: number;

dtsPropsFor.TooltipContent:
/** 深底白字气泡，自带箭头；pointer-events-none（永不截胡点击）；内嵌 Kbd 有专门排版 */
  children?: React.ReactNode;
  side?: "top" | "right" | "bottom" | "left";
  sideOffset?: number;
  align?: "start" | "center" | "end";
  className?: string;

dtsPropsFor.TooltipProvider:
/** 应用级包裹（App 用 delayDuration={400}）；本 DS 的 delayDuration 默认 0 */
  children?: React.ReactNode;
  delayDuration?: number;
  skipDelayDuration?: number;

dtsPropsFor.ContextMenu:
/** 右键菜单根：Trigger 定义右键热区，Content 在指针处弹出 */
  children?: React.ReactNode;
  onOpenChange?: (open: boolean) => void;
  modal?: boolean;

dtsPropsFor.ContextMenuTrigger:
children?: React.ReactNode;
  asChild?: boolean;
  disabled?: boolean;
  className?: string;

dtsPropsFor.ContextMenuContent:
children?: React.ReactNode;
  /** 默认 8：距视口边缘的避让 */
  collisionPadding?: number;
  alignOffset?: number;
  className?: string;

dtsPropsFor.ContextMenuItem:
children?: React.ReactNode;
  /** true 时左侧留出选中标记列宽（与 Checkbox/RadioItem 对齐） */
  inset?: boolean;
  variant?: "default" | "destructive";
  disabled?: boolean;
  onSelect?: (event: Event) => void;
  className?: string;

dtsPropsFor.ContextMenuCheckboxItem:
children?: React.ReactNode;
  checked?: boolean | "indeterminate";
  onCheckedChange?: (checked: boolean) => void;
  inset?: boolean;
  disabled?: boolean;
  className?: string;

dtsPropsFor.ContextMenuRadioItem:
children?: React.ReactNode;
  /** 在外层 RadioGroup 的 value 中的取值 */
  value: string;
  inset?: boolean;
  disabled?: boolean;
  className?: string;

dtsPropsFor.ContextMenuLabel:
/** 分组小标题（muted 小字） */
  children?: React.ReactNode;
  inset?: boolean;
  className?: string;

dtsPropsFor.ContextMenuShortcut:
/** 行尾快捷键提示（ml-auto 靠右） */
  children?: React.ReactNode;
  className?: string;

dtsPropsFor.ContextMenuSub:
children?: React.ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;

dtsPropsFor.ContextMenuSubContent:
/** 子菜单面板：与父级同走 Portal（父级 overflow/transform 会裁剪非 Portal 子菜单） */
  children?: React.ReactNode;
  collisionPadding?: number;
  sideOffset?: number;
  className?: string;

dtsPropsFor.ContextMenuSubTrigger:
/** 自动在行尾追加 ChevronRight 展开指示 */
  children?: React.ReactNode;
  inset?: boolean;
  disabled?: boolean;
  className?: string;

dtsPropsFor.ContextMenuRadioGroup:
children?: React.ReactNode;
  value?: string;
  onValueChange?: (value: string) => void;

dtsPropsFor.ScrollArea:
/** 需要显式高度/最大高度约束才会出现滚动；细滚动条内建（Radix 自绘） */
  children?: React.ReactNode;
  type?: "auto" | "always" | "scroll" | "hover";
  scrollHideDelay?: number;
  className?: string;
